WITH customers_with_transactions_2025 AS (
    SELECT COUNT(DISTINCT CUST_K) AS count
    FROM bank_dwh.F_ACCT_TXN
    WHERE BUS_DT_K IN (
        SELECT DT_K FROM bank_dwh.D_DT WHERE CAL_YR_NBR = 2025
    )
),

customers_total AS (
    SELECT COUNT(DISTINCT BUS_ID) AS count
    FROM bank_dwh.D_CUST
    WHERE IS_CURR = TRUE
)

SELECT customers_total.count - customers_with_transactions_2025.count AS customers_with_no_transactions_2025;
